SELECT s.city, CASE WHEN s.rating >= 4.2 THEN 'high' WHEN s.rating >= 2.4 THEN 'mid' ELSE 'low' END AS rating_bucket, MAX(oi.quantity) - MIN(oi.quantity) AS quantity_range FROM order_items oi INNER JOIN products p ON oi.product_id = p.id LEFT JOIN suppliers s ON p.supplier_id = s.id GROUP BY s.city, CASE WHEN s.rating >= 4.2 THEN 'high' WHEN s.rating >= 2.4 THEN 'mid' ELSE 'low' END ORDER BY quantity_range DESC;
